#!/bin/bash
#-----------------------------------------------------------------------------
# Title      : Add ghdl_synth.mk to the Makefile generated by edalize
# Project    : Asylum
#-----------------------------------------------------------------------------
# File       : ghdl_synth.sh
# Author     : mrosiere
#-----------------------------------------------------------------------------
# Description: pre_run hook of the lint_ghdl_synth_* targets (cwd = fusesoc
#              work_root, Makefile generated by edalize at setup).
#              Appends "include ghdl_synth.mk" to the Makefile (once): the
#              run step (make run EXTRA_OPTIONS=<generics of the target>)
#              then runs ghdl --synth with the options of the target before
#              ghdl -r. See ghdl_synth.mk.
#-----------------------------------------------------------------------------
# Copyright (c) 2026
#-----------------------------------------------------------------------------
# Revisions  :
# Date        Version  Author   Description
# 2026-10-20  1.0      mrosiere Created
# 2026-10-21  2.0      mrosiere Include ghdl_synth.mk in the edalize Makefile,
#                               one fusesoc target per configuration
#-----------------------------------------------------------------------------

MAKEFILE=Makefile
MK=ghdl_synth.mk

for file in "$MAKEFILE" "$MK"; do
    if [ ! -f "$file" ]; then
        echo "ghdl_synth.sh : $file not found in $PWD" >&2
        exit 1
    fi
done

if ! grep -qx "include $MK" "$MAKEFILE"; then
    printf '\n# Added by ghdl_synth.sh (pre_run hook)\ninclude %s\n' "$MK" >> "$MAKEFILE"
fi
